import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [text, setText] = useState("");
  return (
    <View style={styles.screen}>
      <Text style={styles.label}>Таны сэтгэгдэл (Чихэвч)</Text>
      <TextInput nativeID="review" style={styles.box} placeholder="Барааны талаар бичнэ үү..."
        value={text} onChangeText={setText} />
      {/* энд бичнэ үү: review-г multiline болго */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 10 },
  label: { fontSize: 16, fontWeight: "600" },
  box: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 12, padding: 14, height: 120 },
});

registerRootComponent(App);

